// Generates the Uniwind theme and tokens.ts from src/theme/tokens.json (the W3C design
// tokens format, extracted from the Figma file). Never edit the generated files.
//   node scripts/tokens.mjs          write src/theme/generated/{theme.css,tokens.ts,icons.ts}
//   node scripts/tokens.mjs --check  fail if they're out of date (CI)
//
// The theme replaces Tailwind's defaults (palette, fonts, sizes, radii, shadows), so the
// only classes that exist are the design system's.
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';

const SRC = new URL('../src/theme/tokens.json', import.meta.url).pathname;
const ICONS_DIR = new URL('../assets/icons/', import.meta.url).pathname;
const LOGOS_DIR = new URL('../assets/logos/', import.meta.url).pathname;
const OUT_DIR = new URL('../src/theme/generated/', import.meta.url).pathname;
const HEADER = 'Generated by scripts/tokens.mjs from src/theme/tokens.json. Do not edit.';

// Family and weight to the font file loaded in src/theme/fonts.ts.
const FONT_FILES = {
  Staatliches: { 400: 'Staatliches_400Regular' },
  'Schibsted Grotesk': {
    400: 'SchibstedGrotesk_400Regular',
    500: 'SchibstedGrotesk_500Medium',
    600: 'SchibstedGrotesk_600SemiBold',
  },
  'IBM Plex Mono': { 500: 'IBMPlexMono_500Medium', 600: 'IBMPlexMono_600SemiBold' },
};

const tokens = JSON.parse(readFileSync(SRC, 'utf8'));

// --- helpers -------------------------------------------------------------------------

/** Every leaf token as [path segments, token]. */
function leaves(node, path = []) {
  if (node && typeof node === 'object' && '$value' in node) return [[path, node]];
  if (!node || typeof node !== 'object') return [];
  return Object.entries(node)
    .filter(([k]) => !k.startsWith('$'))
    .flatMap(([k, v]) => leaves(v, [...path, k]));
}

function lookup(ref) {
  const path = ref.replace(/^\{|\}$/g, '').split('.');
  let node = tokens;
  for (const key of path) {
    node = node?.[key];
    if (node === undefined) throw new Error(`tokens.json: unknown reference ${ref}`);
  }
  return resolve(node.$value);
}

function resolve(value) {
  if (typeof value === 'string' && /^\{[^}]+\}$/.test(value)) return lookup(value);
  if (Array.isArray(value)) return value.map(resolve);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, resolve(v)]));
  }
  return value;
}

const kebab = (path) => path.join('-').replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const px = (v) => (typeof v === 'number' ? v : Number.parseFloat(String(v)));
const ms = (v) => (typeof v === 'number' ? v : Number.parseFloat(String(v)));

function fontFile(family, weight) {
  const file = FONT_FILES[family]?.[Number(weight)];
  if (!file) {
    throw new Error(
      `tokens.json uses ${family} ${weight}, which src/theme/fonts.ts doesn't load. ` +
        'Add the weight there and to FONT_FILES in scripts/tokens.mjs.',
    );
  }
  return file;
}

function shadowCss(layers) {
  return [layers]
    .flat()
    .map(
      (l) =>
        `${l.inset ? 'inset ' : ''}${px(l.offsetX)}px ${px(l.offsetY)}px ${px(l.blur)}px ${px(l.spread ?? 0)}px ${l.color}`,
    )
    .join(', ');
}

function linearCss(stops, angle) {
  const list = stops.map((s) => `${s.color} ${Math.round(s.position * 1000) / 10}%`).join(', ');
  return `linear-gradient(${angle ?? 180}deg, ${list})`;
}

// --- read every group ----------------------------------------------------------------

const group = (name) => leaves(tokens[name] ?? {}, []);

const colors = Object.fromEntries(
  group('color').map(([p, t]) => [kebab(p), String(resolve(t.$value)).toLowerCase()]),
);
const space = Object.fromEntries(group('space').map(([p, t]) => [kebab(p), px(resolve(t.$value))]));
const radius = Object.fromEntries(
  group('radius').map(([p, t]) => [kebab(p), px(resolve(t.$value))]),
);
const stroke = Object.fromEntries(
  group('stroke').map(([p, t]) => [kebab(p), px(resolve(t.$value))]),
);
const opacity = Object.fromEntries(
  group('opacity').map(([p, t]) => [kebab(p), Number(resolve(t.$value))]),
);
const duration = Object.fromEntries(
  group('duration').map(([p, t]) => [kebab(p), ms(resolve(t.$value))]),
);
const easing = Object.fromEntries(
  group('easing').map(([p, t]) => [kebab(p), resolve(t.$value).map(Number)]),
);
const fontFamilies = Object.fromEntries(
  group('font').map(([p, t]) => [kebab(p), resolve(t.$value)]),
);

const typography = Object.fromEntries(
  group('typography').map(([p, t]) => {
    const v = resolve(t.$value);
    const style = {
      fontFamily: fontFile(v.fontFamily, v.fontWeight ?? 400),
      fontSize: px(v.fontSize),
      lineHeight: px(v.lineHeight),
      letterSpacing: px(v.letterSpacing ?? 0),
    };
    if (v.textTransform) style.textTransform = v.textTransform;
    return [kebab(p), style];
  }),
);

const shadows = Object.fromEntries(group('shadow').map(([p, t]) => [kebab(p), resolve(t.$value)]));
const gradients = Object.fromEntries(
  group('gradient').map(([p, t]) => [
    kebab(p),
    { stops: resolve(t.$value), ...(t.$extensions ?? {}) },
  ]),
);

// --- theme.css -----------------------------------------------------------------------

const css = [];
css.push(`/* ${HEADER} */`, '', '@theme {');
for (const ns of [
  'color',
  'font',
  'text',
  'radius',
  'shadow',
  'inset-shadow',
  'drop-shadow',
  'tracking',
  'leading',
  'blur',
]) {
  css.push(`  --${ns}-*: initial;`);
}
css.push('  --spacing: 4px;');
for (const [name, value] of Object.entries(colors)) css.push(`  --color-${name}: ${value};`);
for (const [name, value] of Object.entries(radius)) css.push(`  --radius-${name}: ${value}px;`);
// No font-* classes: type is set only through the type-* utilities (the Text component).
css.push('}', '');

for (const [name, t] of Object.entries(typography)) {
  css.push(`@utility type-${name} {`);
  css.push(`  font-family: ${t.fontFamily};`);
  css.push(`  font-size: ${t.fontSize}px;`);
  css.push(`  line-height: ${t.lineHeight}px;`);
  css.push(`  letter-spacing: ${t.letterSpacing}px;`);
  if (t.textTransform) css.push(`  text-transform: ${t.textTransform};`);
  css.push('}');
}
for (const [name, layers] of Object.entries(shadows)) {
  css.push(`@utility ${name} {`, `  box-shadow: ${shadowCss(layers)};`, '}');
}
for (const [name, g] of Object.entries(gradients)) {
  if (g.kind === 'radial') continue; // native gradients are linear only: see SpotlightBackdrop
  css.push(
    `@utility gradient-${name} {`,
    `  background-image: ${linearCss(g.stops, g.angle)};`,
    '}',
  );
}
for (const [name, value] of Object.entries(stroke)) {
  css.push(`@utility stroke-${name} {`, `  border-width: ${value}px;`, '}');
}
for (const [name, value] of Object.entries(opacity)) {
  css.push(`@utility opacity-${name} {`, `  opacity: ${value};`, '}');
}
const themeCss = `${css.join('\n')}\n`;

// --- tokens.ts -----------------------------------------------------------------------

const ts = `// ${HEADER}
// For what classes can't do: Reanimated styles, SVG, gradients, motion.

export const tokens = ${JSON.stringify(
  {
    color: colors,
    space,
    radius,
    stroke,
    opacity,
    font: fontFamilies,
    typography,
    shadow: Object.fromEntries(Object.entries(shadows).map(([k, v]) => [k, shadowCss(v)])),
    gradient: gradients,
    duration,
    easing,
  },
  null,
  2,
)} as const;

export type ColorToken = keyof typeof tokens.color;
export type TypographyToken = keyof typeof tokens.typography;
export type ShadowToken = keyof typeof tokens.shadow;
export type GradientToken = keyof typeof tokens.gradient;
export type DurationToken = keyof typeof tokens.duration;
`;

// --- icons.ts ------------------------------------------------------------------------
// The Figma's icons (assets/icons/*.svg, exported from the Icons frame, strokes in
// currentColor), as strings for react-native-svg's SvgXml.

const iconFiles = readdirSync(ICONS_DIR)
  .filter((f) => f.endsWith('.svg'))
  .sort();
const iconEntries = iconFiles.map((f) => {
  const svg = readFileSync(ICONS_DIR + f, 'utf8')
    .trim()
    .replace(/\s*\n\s*/g, ' ');
  return `  '${f.replace(/\.svg$/, '')}': ${JSON.stringify(svg)},`;
});
const iconsTs = `// ${HEADER.replace('src/theme/tokens.json', 'assets/icons/*.svg')}

export const icons = {
${iconEntries.join('\n')}
} as const;

export type IconName = keyof typeof icons;

// Third-party marks in their own colours (assets/logos/*.svg). Not for anything else.
export const logos = {
${readdirSync(LOGOS_DIR)
  .filter((f) => f.endsWith('.svg'))
  .sort()
  .map((f) => {
    const svg = readFileSync(LOGOS_DIR + f, 'utf8')
      .trim()
      .replace(/\s(preserveAspectRatio|overflow|style|id)="[^"]*"/g, '')
      .replace(/\s*\n\s*/g, ' ');
    return `  '${f.replace(/\.svg$/, '')}': ${JSON.stringify(svg)},`;
  })
  .join('\n')}
} as const;

export type LogoName = keyof typeof logos;
`;

// --- write or check ------------------------------------------------------------------

const outputs = { 'theme.css': themeCss, 'tokens.ts': ts, 'icons.ts': iconsTs };
if (process.argv.includes('--check')) {
  const stale = Object.entries(outputs).filter(
    ([file, content]) =>
      !existsSync(OUT_DIR + file) || readFileSync(OUT_DIR + file, 'utf8') !== content,
  );
  if (stale.length) {
    console.error(
      `Out of date: ${stale.map(([f]) => f).join(', ')}. Run \`pnpm tokens\` in mobile/.`,
    );
    process.exit(1);
  }
  console.log('Tokens: generated files are up to date.');
} else {
  mkdirSync(OUT_DIR, { recursive: true });
  for (const [file, content] of Object.entries(outputs)) writeFileSync(OUT_DIR + file, content);
  console.log(
    `Tokens: ${Object.keys(colors).length} colors, ${Object.keys(typography).length} type styles, ` +
      `${Object.keys(shadows).length} shadows, ${Object.keys(gradients).length} gradients.`,
  );
}
